#!/usr/bin/env node
/**
 * Assert the README's status table is what the harness actually produces.
 *
 * A hand-maintained status table drifts, and a drifted one is worse than none: it is read as current, and
 * the reader has no way to tell that it stopped being true. So the table is generated by
 * `golden-e2e.mjs --readme` and pinned here.
 *
 * The same discipline the shipped-copy check applies to the SOP and templates, applied to the headline
 * claim — which is the one most likely to be edited by hand and least likely to be re-run.
 *
 * Usage: node --experimental-strip-types scripts/check-readme-status.mjs
 * Exit codes: 0 current · 1 drifted · 2 could not run
 */

import { readFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const REPO = resolve(HERE, '..')
const README = join(REPO, 'README.md')

const generated = spawnSync(
  process.execPath,
  ['--experimental-strip-types', join(HERE, 'golden-e2e.mjs'), '--readme'],
  { cwd: REPO, encoding: 'utf8' },
)
if (generated.status !== 0) {
  process.stderr.write(`cannot run: golden-e2e --readme exited ${generated.status}\n${generated.stderr ?? ''}\n`)
  process.exit(2)
}

const table = generated.stdout.trim()
const readme = readFileSync(README, 'utf8')

if (readme.includes(table)) {
  process.stdout.write('✓ the README status table matches the golden E2E\n')
  process.exit(0)
}

process.stderr.write(
  'error: the README status table does not match what the golden E2E produces.\n\n'
  + 'expected to find:\n'
  + `${table.split('\n').map((line) => `  ${line}`).join('\n')}\n\n`
  + 'The table is generated, not maintained. Re-run the harness and paste its --readme output:\n'
  + '  node --experimental-strip-types scripts/golden-e2e.mjs --readme\n',
)
process.exit(1)
